  async function checkSetup(){
    try{const data=await api("/api/setup/status");app.setupRequired=!!data.needs_setup;applyInstitutionBrand(data.institution||"");if(els.setupShell)els.setupShell.classList.toggle("hidden",!app.setupRequired);if(els.appShell)els.appShell.classList.toggle("hidden",app.setupRequired);if(app.setupRequired){els.setupAcademicYear.value=String(new Date().getFullYear());els.setupLanguage.value=I18N?.language?.()||"es";return true;}return false;}catch(_){setConnection(false);return false;}
  }
  async function completeSetup(e){
    e.preventDefault();if(els.setupPassword.value!==els.setupPasswordRepeat.value)return toast("Las contraseñas no coinciden.");
    try{const data=await api("/api/setup",{method:"POST",body:{institution_name:els.setupInstitution.value,name:els.setupName.value,email:els.setupEmail.value,academic_year:els.setupAcademicYear.value,language:els.setupLanguage.value,password:els.setupPassword.value}});app.user=data.user;app.csrf=data.csrf_token||"";app.setupRequired=false;applyInstitutionBrand(els.setupInstitution.value);els.setupShell.classList.add("hidden");els.appShell.classList.remove("hidden");if(data.user?.preferred_language)I18N?.setLanguage?.(data.user.preferred_language);await loadClassrooms();updateAuthUI();renderClassroomCards();toast("Configuración inicial completada.");switchView("homeView");}catch(err){toast(err.message);}
  }
  async function checkBackendAndSession(){
    try{await api("/api/status");}catch(_){app.user=null;app.csrf="";updateAuthUI();switchView("accountView");return;}
    if(await checkSetup())return;
    try{const data=await api("/api/auth/me");app.user=data.user;app.csrf=data.csrf_token||"";app.google=data.google||null;if(app.user?.preferred_language&&I18N?.language?.()!==app.user.preferred_language)I18N?.setLanguage?.(app.user.preferred_language);await loadClassrooms();updateAuthUI();renderClassroomCards();switchView("homeView");syncPendingDrafts();}catch(e){if(e.status!==401)console.error(e);app.user=null;app.csrf="";app.google=null;updateAuthUI();switchView("accountView");}
  }
  async function loadClassrooms(){if(!app.user){app.classrooms=[];return;}const data=await api("/api/classrooms");app.classrooms=data.classrooms||[];populateClassroomSelects();}
  function populateClassroomSelects(){
    const options=app.classrooms.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join("");
    [els.studentClassroomInput,els.assessmentClassroom].forEach(s=>{if(s)s.innerHTML=options;});
    if(els.scheduleClassroom)els.scheduleClassroom.innerHTML=`<option value="">${esc(t("Sin aula"))}</option>${options}`;
    if(els.gradesClassroom)els.gradesClassroom.innerHTML=app.classrooms.length?options:`<option value="">${esc(t("Sin aulas asignadas"))}</option>`;
    if(els.historyClassroom)els.historyClassroom.innerHTML=`<option value="all">${esc(t("Todas mis aulas"))}</option>${options}`;
    if(els.reportClassroom)els.reportClassroom.innerHTML=`<option value="all">${esc(t("Todas mis aulas"))}</option>${options}`;
  }

  async function renderHome(){
    if(!app.user)return;els.homeDate.textContent=formatDate(today());
    try{
      const [schedule,alerts]=await Promise.all([api(`/api/schedule/today?date=${today()}`),api("/api/alerts")]);
      const items=schedule.items||[];els.todayClassesList.innerHTML=items.map(item=>`<article class="today-class-card"><div class="time-badge">${esc(item.start_time||"—")}</div><div><strong data-i18n-skip>${esc(item.title)}</strong><span>${esc(item.classroom_name||t("Sin aula"))} · ${esc(scheduleKindText(item.kind))}</span></div>${item.kind==="class"&&item.classroom_id?`<button class="primary-button today-attendance" data-class="${esc(item.classroom_id)}">${esc(t("Pasar lista"))}</button>`:""}</article>`).join("");els.noTodayClasses.classList.toggle("hidden",items.length>0);$$('.today-attendance').forEach(b=>b.addEventListener("click",async()=>{switchView("attendanceView");await openClassroom(b.dataset.class);}));
      const rows=alerts.alerts||[];els.alertsList.innerHTML=rows.map(a=>`<button class="alert-card" data-student="${esc(a.student_id)}"><strong data-i18n-skip>${esc(a.student_name)}</strong><span>${esc(a.classroom_name)} · ${esc(alertText(a))}</span></button>`).join("");els.noAlerts.classList.toggle("hidden",rows.length>0);$$('.alert-card').forEach(b=>b.addEventListener("click",()=>openStudentProfile(b.dataset.student)));
    }catch(e){toast(e.message);}
  }
  function alertText(a){if(a.type==="consecutive_absences")return t(`${a.value} ausencias consecutivas`);if(a.type==="monthly_lates")return t(`${a.value} llegadas tarde este mes`);if(a.type==="low_attendance")return `${t("Asistencia baja")}: ${a.value}% (< ${a.threshold}%)`;return a.type;}
  function scheduleKindText(k){return t({class:"Clase",assessment:"Evaluación",meeting:"Reunión",reminder:"Recordatorio"}[k]||k);}

  function renderClassroomCards(){els.classroomGrid.innerHTML="";const rows=app.classrooms||[];els.noClassroomsAttendance.classList.toggle("hidden",rows.length>0);rows.forEach(c=>{const b=document.createElement("button");b.className="classroom-card";b.innerHTML=`<strong data-i18n-skip>${esc(c.name)}</strong><span>${c.student_count??0} ${t((c.student_count??0)===1?"alumno":"alumnos")}</span>`;b.addEventListener("click",()=>openClassroom(c.id));els.classroomGrid.appendChild(b);});}

  function localDraftKey(date,classroomId){return `${DRAFT_PREFIX}${app.user?.id||"anon"}:${date}:${classroomId}`;}
  function draftRecords(){return app.students.map(s=>({student_id:s.id,status:app.draftAttendance[s.id]?.status||"",reason:app.draftAttendance[s.id]?.reason||"",arrival_time:app.draftAttendance[s.id]?.arrival_time||"",departure_time:app.draftAttendance[s.id]?.departure_time||""}));}
  function persistLocalDraft(){if(!app.user||!app.selectedClassroomId)return;const payload={date:els.attendanceDate.value,classroom_id:app.selectedClassroomId,records:draftRecords(),updated_at:new Date().toISOString()};localStorage.setItem(localDraftKey(payload.date,payload.classroom_id),JSON.stringify(payload));return payload;}
  function loadLocalDraft(date,classroomId){try{return JSON.parse(localStorage.getItem(localDraftKey(date,classroomId))||"null");}catch(_){return null;}}
  function clearLocalDraft(date,classroomId){localStorage.removeItem(localDraftKey(date,classroomId));}
  function recordsToDraft(records){const out={};(records||[]).forEach(r=>out[r.student_id]={status:r.status||"",reason:r.reason||"",arrival_time:r.arrival_time||"",departure_time:r.departure_time||""});return out;}

  async function openClassroom(classroomId){
    try{
      app.selectedClassroomId=classroomId;const date=els.attendanceDate.value;
      const [studentsData,attendanceData,draftData]=await Promise.all([api(`/api/students?classroom_id=${encodeURIComponent(classroomId)}`),api(`/api/attendance?date=${encodeURIComponent(date)}&classroom_id=${encodeURIComponent(classroomId)}`),api(`/api/attendance/draft?date=${encodeURIComponent(date)}&classroom_id=${encodeURIComponent(classroomId)}`).catch(()=>({draft:null,updated_at:null}))]);
      app.students=studentsData.students||[];app.draftAttendance=recordsToDraft(attendanceData.attendance||[]);let recovered=false;
      const local=loadLocalDraft(date,classroomId);const backendDraft=draftData.draft?{...draftData.draft,updated_at:draftData.updated_at}:null;
      const candidates=[local,backendDraft].filter(Boolean).sort((a,b)=>String(a.updated_at||"").localeCompare(String(b.updated_at||"")));
      if(candidates.length){const latest=candidates[candidates.length-1];if(Array.isArray(latest.records)){app.draftAttendance={...app.draftAttendance,...recordsToDraft(latest.records)};recovered=true;}}
      els.classroomSelectorPanel.classList.add("hidden");els.attendancePanel.classList.remove("hidden");setAttendanceDirty(recovered);renderAttendance();if(recovered)els.autosaveStatus.textContent=t("Borrador recuperado");
    }catch(e){toast(e.message);}
  }
  function closeClassroom(){if(app.attendanceDirty)persistLocalDraft();app.selectedClassroomId=null;app.students=[];app.draftAttendance={};app.attendanceDirty=false;els.attendancePanel.classList.add("hidden");els.classroomSelectorPanel.classList.remove("hidden");}
  function setAttendanceDirty(value){app.attendanceDirty=!!value;els.attendanceStatus.textContent=t(value?"Hay cambios sin guardar":"Sin cambios");}
  function statusCell(studentId,status,selected){return `<td><button class="status-option ${selected===status?"selected":""}" data-student-id="${esc(studentId)}" data-status="${status}" aria-label="${esc(statusText(status))}"></button></td>`;}
  function detailRow(student){
    const d=app.draftAttendance[student.id]||{};const status=d.status||"";if(!["absent","justified","late","early_departure"].includes(status))return "";
    let controls="";
    if(["absent","justified","early_departure"].includes(status))controls+=`<label class="attendance-detail-field"><span>${esc(t("Motivo"))}</span><select class="attendance-reason" data-student-id="${esc(student.id)}"><option value="">${esc(t("Sin motivo cargado"))}</option>${["Enfermedad","Familiar","Actividad institucional","Transporte","Otro"].map(x=>`<option ${d.reason===x?"selected":""}>${esc(t(x))}</option>`).join("")}</select></label>`;
    if(status==="late")controls+=`<label class="attendance-detail-field"><span>${esc(t("Hora de llegada"))}</span><input class="attendance-arrival" data-student-id="${esc(student.id)}" type="time" value="${esc(d.arrival_time||"")}"></label>`;
    if(status==="early_departure")controls+=`<label class="attendance-detail-field"><span>${esc(t("Hora de retiro"))}</span><input class="attendance-departure" data-student-id="${esc(student.id)}" type="time" value="${esc(d.departure_time||"")}"></label>`;
    return `<tr class="attendance-detail-row"><td colspan="6"><div class="attendance-details">${controls}</div></td></tr>`;
  }
  function renderAttendance(){
    const classroom=app.classrooms.find(c=>c.id===app.selectedClassroomId);if(!classroom)return closeClassroom();els.attendanceClassroomName.textContent=classroom.name;els.attendanceSubline.textContent=`${app.students.length} ${t(app.students.length===1?"alumno":"alumnos")} · ${formatDate(els.attendanceDate.value)}`;els.attendanceBody.innerHTML="";els.noStudentsAttendance.classList.toggle("hidden",app.students.length>0);els.saveAttendance.disabled=!app.students.length;
    app.students.forEach(s=>{const d=app.draftAttendance[s.id]||{},selected=d.status||"";const tr=document.createElement("tr");tr.innerHTML=`<td><button class="student-link" data-student="${esc(s.id)}"><strong data-i18n-skip>${esc(s.name)}</strong><small>Legajo ${esc(s.record_number)}</small></button></td>${statusCell(s.id,"present",selected)}${statusCell(s.id,"absent",selected)}${statusCell(s.id,"late",selected)}${statusCell(s.id,"justified",selected)}${statusCell(s.id,"early_departure",selected)}`;els.attendanceBody.appendChild(tr);const details=detailRow(s);if(details)els.attendanceBody.insertAdjacentHTML("beforeend",details);});
    $$('#attendanceBody .status-option').forEach(btn=>btn.addEventListener("click",()=>{const id=btn.dataset.studentId,status=btn.dataset.status,prev=app.draftAttendance[id]||{};app.draftAttendance[id]={status,reason:["absent","justified","early_departure"].includes(status)?prev.reason||"":"",arrival_time:status==="late"?prev.arrival_time||"":"",departure_time:status==="early_departure"?prev.departure_time||"":""};setAttendanceDirty(true);persistLocalDraft();renderAttendance();}));
    $$('#attendanceBody .student-link').forEach(b=>b.addEventListener("click",()=>openStudentProfile(b.dataset.student)));
    $$('#attendanceBody .attendance-reason').forEach(el=>el.addEventListener("change",()=>{app.draftAttendance[el.dataset.studentId].reason=el.value;setAttendanceDirty(true);persistLocalDraft();}));
    $$('#attendanceBody .attendance-arrival').forEach(el=>el.addEventListener("change",()=>{app.draftAttendance[el.dataset.studentId].arrival_time=el.value;setAttendanceDirty(true);persistLocalDraft();}));
    $$('#attendanceBody .attendance-departure').forEach(el=>el.addEventListener("change",()=>{app.draftAttendance[el.dataset.studentId].departure_time=el.value;setAttendanceDirty(true);persistLocalDraft();}));
    updateSummary();
  }
  function updateSummary(){const c={present:0,absent:0,late:0,justified:0,early_departure:0};Object.values(app.draftAttendance).forEach(d=>{if(d?.status in c)c[d.status]++;});els.presentCount.textContent=c.present;els.absentCount.textContent=c.absent;els.lateCount.textContent=c.late;els.justifiedCount.textContent=c.justified;els.earlyCount.textContent=c.early_departure;}
  function markAllPresent(){app.students.forEach(s=>app.draftAttendance[s.id]={status:"present",reason:"",arrival_time:"",departure_time:""});setAttendanceDirty(true);persistLocalDraft();renderAttendance();}
  async function autosaveAttendanceDraft(){
    if(!app.attendanceDirty||!app.selectedClassroomId||!app.user)return;const payload=persistLocalDraft();
    try{const result=await api("/api/attendance/draft",{method:"POST",body:payload});els.autosaveStatus.textContent=`${t("Borrador guardado")} · ${formatDateTime(result.updated_at)}`;}catch(_){els.autosaveStatus.textContent=t("Borrador local · sin conexión");}
  }
  async function saveAttendance(){
    const missing=app.students.filter(s=>!app.draftAttendance[s.id]?.status);if(missing.length)return toast(`${t("Faltan marcar")} ${missing.length} ${t(missing.length===1?"alumno":"alumnos")}.`);
    const payload={date:els.attendanceDate.value,classroom_id:app.selectedClassroomId,records:draftRecords()};
    try{const result=await api("/api/attendance/save",{method:"POST",body:payload});clearLocalDraft(payload.date,payload.classroom_id);setAttendanceDirty(false);els.autosaveStatus.textContent=`${t("Guardado")} · ${formatDateTime(result.saved_at)}`;toast("Asistencia guardada.");await renderHome();}
    catch(e){persistLocalDraft();els.autosaveStatus.textContent=t("Borrador local · sin conexión");toast(e.message||"No se pudo guardar en el servidor. El borrador quedó local.");}
  }
  async function syncPendingDrafts(){if(!app.user||!app.backendOnline)return;for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key?.startsWith(`${DRAFT_PREFIX}${app.user.id}:`))continue;try{const payload=JSON.parse(localStorage.getItem(key));await api("/api/attendance/draft",{method:"POST",body:payload});}catch(_){}}}

  function attendanceDetailText(r){const parts=[];if(r.reason)parts.push(t(r.reason));if(r.arrival_time)parts.push(`${t("Llegada")}: ${r.arrival_time}`);if(r.departure_time)parts.push(`${t("Retiro")}: ${r.departure_time}`);return parts.join(" · ")||"—";}
  async function renderHistory(){
    if(!app.user)return;populateClassroomSelects();try{const data=await api(`/api/history?date=${encodeURIComponent(els.historyDate.value)}&classroom_id=${encodeURIComponent(els.historyClassroom.value||"all")}`);const rows=data.attendance||[];els.historyBody.innerHTML=rows.map(r=>`<tr><td><button class="student-link history-student" data-student="${esc(r.student_id)}" data-i18n-skip>${esc(r.student_name)}</button></td><td data-i18n-skip>${esc(r.classroom_name)}</td><td><span class="status-badge ${esc(r.status)}">${esc(statusText(r.status))}</span></td><td>${esc(attendanceDetailText(r))}</td><td data-i18n-skip>${esc(r.updated_by_name)}</td></tr>`).join("");els.noHistory.classList.toggle("hidden",rows.length>0);const counts={};rows.forEach(r=>counts[r.status]=(counts[r.status]||0)+1);els.historySummary.innerHTML=Object.entries(counts).map(([s,n])=>`<span class="history-chip">${n} ${esc(statusText(s))}</span>`).join("");$$('.history-student').forEach(b=>b.addEventListener("click",()=>openStudentProfile(b.dataset.student)));}catch(e){toast(e.message);}
  }

