  async function loadAssessments(){const cid=els.gradesClassroom.value;if(!cid)return;try{const data=await api(`/api/assessments?classroom_id=${encodeURIComponent(cid)}`);const rows=data.assessments||[];els.assessmentList.innerHTML=rows.map(a=>`<article class="assessment-card"><div><strong data-i18n-skip>${esc(a.title)}</strong><span>${formatDate(a.assessment_date)} · ${t("Máximo")} ${a.max_score}</span><small>${a.graded_count||0} ${t("calificados")}</small></div><button class="secondary-button open-grades" data-id="${esc(a.id)}">${esc(t("Abrir"))}</button></article>`).join("");els.noAssessments.classList.toggle("hidden",rows.length>0);$$('.open-grades').forEach(b=>b.addEventListener("click",()=>openGradesDialog(b.dataset.id)));}catch(e){toast(e.message);}}
  function openAssessmentDialog(){if(!app.classrooms.length)return toast("No hay aulas asignadas.");populateClassroomSelects();els.assessmentForm.reset();els.assessmentClassroom.value=els.gradesClassroom.value||app.classrooms[0].id;els.assessmentDate.value=today();els.assessmentMaxScore.value="10";els.assessmentDialog.showModal();}
