  async function renderCalendar(){if(!app.user)return;populateClassroomSelects();els.scheduleDate.value=els.scheduleDate.value||today();try{const data=await api("/api/schedule");const rows=data.items||[];els.scheduleList.innerHTML=rows.map(i=>`<article class="schedule-card"><div><span class="kind-pill">${esc(scheduleKindText(i.kind))}</span><strong data-i18n-skip>${esc(i.title)}</strong><span>${formatDate(i.event_date)}${i.start_time?` · ${esc(i.start_time)}`:""}${i.classroom_name?` · ${esc(i.classroom_name)}`:""}</span>${i.note?`<small data-i18n-skip>${esc(i.note)}</small>`:""}${i.repeat_weekly?`<small>${esc(t("Repite semanalmente"))}</small>`:""}</div><button class="icon-button delete-schedule" data-id="${esc(i.id)}" title="${esc(t("Eliminar"))}">×</button></article>`).join("");els.noSchedule.classList.toggle("hidden",rows.length>0);$$('.delete-schedule').forEach(b=>b.addEventListener("click",()=>deleteSchedule(b.dataset.id)));}catch(e){toast(e.message);}}
  async function createSchedule(e){e.preventDefault();try{await api("/api/schedule",{method:"POST",body:{kind:els.scheduleKind.value,title:els.scheduleTitle.value,classroom_id:els.scheduleClassroom.value,event_date:els.scheduleDate.value,start_time:els.scheduleTime.value,note:els.scheduleNote.value,repeat_weekly:els.scheduleRepeat.checked}});els.scheduleForm.reset();els.scheduleDate.value=today();toast("Evento guardado.");await renderCalendar();await renderHome();}catch(err){toast(err.message);}}
