  function renderClassroomAdmin(){els.classroomAdminList.innerHTML=app.classrooms.map(c=>`<div class="admin-row"><div class="admin-row-main"><strong data-i18n-skip>${esc(c.name)}</strong><small>${c.student_count??0} ${t((c.student_count??0)===1?"alumno":"alumnos")}</small></div><div class="row-actions"><button class="secondary-button rename-classroom" data-id="${esc(c.id)}">${esc(t("Renombrar"))}</button><button class="danger-button delete-classroom" data-id="${esc(c.id)}">${esc(t("Eliminar"))}</button></div></div>`).join("");$$('.rename-classroom').forEach(b=>b.addEventListener("click",()=>renameClassroom(b.dataset.id)));$$('.delete-classroom').forEach(b=>b.addEventListener("click",()=>deleteClassroom(b.dataset.id)));}
  function renderStudentAdmin(){els.studentFilter.innerHTML=`<option value="all">${esc(t("Todos los alumnos"))}</option>${app.classrooms.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join("")}`;const filter=els.studentFilter.dataset.last||"all";if([...els.studentFilter.options].some(o=>o.value===filter))els.studentFilter.value=filter;const rows=app.students.filter(s=>els.studentFilter.value==="all"||s.classroom_id===els.studentFilter.value);els.studentAdminList.innerHTML=rows.map(s=>`<div class="admin-row"><div class="admin-row-main"><strong data-i18n-skip>${esc(s.name)}</strong><small>Legajo ${esc(s.record_number)} · ${esc(s.classroom_name)}</small>${s.protected?`<small class="protected-record">${esc(t("Protegido por reportes o notas"))}</small>`:""}</div><div class="row-actions"><button class="secondary-button view-student" data-id="${esc(s.id)}">${esc(t("Ver"))}</button><button class="secondary-button edit-student" data-id="${esc(s.id)}">${esc(t("Editar"))}</button><button class="danger-button delete-student" data-id="${esc(s.id)}" ${s.protected?"disabled":""}>${esc(t("Dar de baja"))}</button></div></div>`).join("");$$('.view-student').forEach(b=>b.addEventListener("click",()=>openStudentProfile(b.dataset.id)));$$('.edit-student').forEach(b=>b.addEventListener("click",()=>openStudentDialog(b.dataset.id)));$$('.delete-student').forEach(b=>b.addEventListener("click",()=>deleteStudent(b.dataset.id)));}
  function renderUserAdmin(){els.userAdminList.innerHTML=app.adminUsers.map(u=>`<div class="admin-row"><div class="admin-row-main"><strong data-i18n-skip>${esc(u.name)}</strong><small data-i18n-skip>${esc(u.email)} · ${esc(roleLabel(u.role))}</small></div><button class="secondary-button edit-user" data-id="${esc(u.id)}">${esc(t("Editar"))}</button></div>`).join("");$$('.edit-user').forEach(b=>b.addEventListener("click",()=>openUserDialog(b.dataset.id)));}
  async function renameClassroom(id){const c=app.classrooms.find(x=>x.id===id);if(!c)return;const name=prompt(t("Nuevo nombre del aula:"),c.name);if(name===null)return;try{await api(`/api/classrooms/${encodeURIComponent(id)}`,{method:"PATCH",body:{name}});toast("Aula renombrada.");await loadClassrooms();await renderAdmin();renderClassroomCards();}catch(e){toast(e.message);}}
