  async function saveStudent(e){e.preventDefault();const id=els.studentIdInput.value;const body={name:els.studentNameInput.value,record_number:els.studentRecordInput.value,classroom_id:els.studentClassroomInput.value,dni:els.studentDniInput.value,birth_date:els.studentBirthDateInput.value,guardian_name:els.studentGuardianNameInput.value,guardian_phone:els.studentGuardianPhoneInput.value,guardian_email:els.studentGuardianEmailInput.value,emergency_name:els.studentEmergencyNameInput.value,emergency_phone:els.studentEmergencyPhoneInput.value};try{await api(id?`/api/students/${encodeURIComponent(id)}`:"/api/students",{method:id?"PATCH":"POST",body});els.studentDialog.close();toast(id?"Alumno actualizado.":"Alumno agregado.");await loadClassrooms();await renderAdmin();renderClassroomCards();}catch(err){toast(err.message);}}
