      const s=sd.student;app.currentProfileStudent=s;els.profileStudentName.textContent=s.name;els.profileStudentMeta.textContent=`${t("Legajo")} #${s.record_number} · ${s.classroom_name}`;
      const summary=s.attendance_summary||{};const contacts=app.user.permissions.view_contacts?`<div class="info-card"><small>${esc(t("Madre, padre o tutor"))}</small><strong data-i18n-skip>${esc(s.guardian_name||t("No cargado"))}</strong><span data-i18n-skip>${esc(s.guardian_phone||"—")}</span><span data-i18n-skip>${esc(s.guardian_email||"—")}</span></div><div class="info-card"><small>${esc(t("Contacto de emergencia"))}</small><strong data-i18n-skip>${esc(s.emergency_name||t("No cargado"))}</strong><span data-i18n-skip>${esc(s.emergency_phone||"—")}</span></div>`:`<div class="info-card span-2"><small>${esc(t("Datos de contacto"))}</small><strong>${esc(t("Restringidos al rol de preceptor/directivo"))}</strong></div>`;
      els.profileInfoTab.innerHTML=`<div class="profile-summary-strip"><div><small>${esc(t("Asistencia"))}</small><strong>${summary.attendance_rate==null?"—":summary.attendance_rate+"%"}</strong></div><div><small>${esc(t("Ausentes"))}</small><strong>${summary.absent||0}</strong></div><div><small>${esc(t("Tarde"))}</small><strong>${summary.late||0}</strong></div><div><small>${esc(t("Justificadas"))}</small><strong>${summary.justified||0}</strong></div></div><div class="info-grid"><div class="info-card"><small>DNI</small><strong data-i18n-skip>${esc(s.dni||t("Restringido"))}</strong></div><div class="info-card"><small>${esc(t("Fecha de nacimiento"))}</small><strong>${formatDate(s.birth_date)}</strong></div>${contacts}</div>`;
      const attendance=ad.attendance||[],audit=auditData.audit||[];els.profileAttendanceTab.innerHTML=`<div class="profile-export-actions"><button class="secondary-button profile-history-export" data-format="csv">${esc(t("Historial CSV"))}</button><button class="secondary-button profile-history-export" data-format="pdf">${esc(t("Historial PDF"))}</button></div>${attendance.length?`<div class="table-wrap"><table><thead><tr><th>${esc(t("Fecha"))}</th><th>${esc(t("Estado"))}</th><th>${esc(t("Detalle"))}</th><th>${esc(t("Actualizado por"))}</th></tr></thead><tbody>${attendance.map(r=>`<tr><td>${formatDate(r.date)}</td><td><span class="status-badge ${esc(r.status)}">${esc(statusText(r.status))}</span></td><td>${esc(attendanceDetailText(r))}</td><td data-i18n-skip>${esc(r.updated_by_name)}</td></tr>`).join("")}</tbody></table></div>`:`<div class="empty-state"><strong>${esc(t("Sin asistencia registrada."))}</strong></div>`}<div class="audit-section"><h3>${esc(t("Registro de modificaciones"))}</h3>${audit.length?`<div class="audit-list">${audit.map(a=>`<div class="audit-item"><strong>${esc(formatDateTime(a.changed_at))}</strong><span>${esc(statusText(a.old_status||""))} → ${esc(statusText(a.new_status||""))}</span><small data-i18n-skip>${esc(a.changed_by_name)}</small></div>`).join("")}</div>`:`<p class="muted">${esc(t("No hay modificaciones registradas."))}</p>`}</div>`;$$('.profile-history-export').forEach(b=>b.addEventListener("click",()=>exportStudentHistory(b.dataset.format)));
      const reports=rd.reports||[];els.profileReportsTab.innerHTML=reports.length?reports.map(r=>reportCardHtml(r,false,true)).join(""):`<div class="empty-state"><strong>${esc(t("No hay reportes visibles para tu cuenta."))}</strong></div>`;
      const notes=nd.notes||[];app.currentProfileNotes=notes;els.profileNotesTab.innerHTML=notes.length?notes.map(n=>`<article class="note-card"><p data-i18n-skip>${esc(n.note)}</p><div><small>${formatDateTime(n.updated_at||n.created_at)}</small><span class="row-actions"><button class="text-button edit-note-profile" data-id="${esc(n.id)}">${esc(t("Editar"))}</button><button class="text-button delete-note" data-id="${esc(n.id)}">${esc(t("Eliminar"))}</button></span></div></article>`).join(""):`<div class="empty-state"><strong>${esc(t("No tenés notas privadas sobre este alumno."))}</strong></div>`;
      const grades=gd.grades||[];els.profileGradesTab.innerHTML=grades.length?`<div class="table-wrap"><table><thead><tr><th>${esc(t("Evaluación"))}</th><th>${esc(t("Fecha"))}</th><th>${esc(t("Nota"))}</th><th>${esc(t("Observación"))}</th></tr></thead><tbody>${grades.map(g=>`<tr><td data-i18n-skip>${esc(g.title)}</td><td>${formatDate(g.assessment_date)}</td><td>${g.score==null?"—":`${g.score} / ${g.max_score}`}</td><td data-i18n-skip>${esc(g.comment||"—")}</td></tr>`).join("")}</tbody></table></div>`:`<div class="empty-state"><strong>${esc(t("Sin calificaciones cargadas."))}</strong></div>`;
      const notices=wd.notices||[];els.profileNoticesTab.innerHTML=notices.length?notices.map(n=>`<article class="notice-card"><div><strong data-i18n-skip>${esc(n.reason)}</strong><span>${formatDateTime(n.created_at)} · ${esc(t(n.status==="sent"?"Enviado":"Generado"))}</span></div><p data-i18n-skip>${esc(n.message)}</p>${n.status!=="sent"?`<button class="secondary-button mark-notice-sent" data-id="${esc(n.id)}">${esc(t("Marcar como enviado"))}</button>`:""}</article>`).join(""):`<div class="empty-state"><strong>${esc(t("No hay avisos registrados."))}</strong></div>`;
