  async function saveProfile(e){e.preventDefault();try{const data=await api("/api/profile",{method:"PATCH",body:{name:els.profileNameInput.value,email:els.profileEmailInput.value,preferred_language:els.profileLanguageInput.value,avatar_url:els.profileAvatarInput.value,use_google_picture:els.profileUseGooglePicture.checked}});app.user=data.user;if(app.user.preferred_language)I18N?.setLanguage?.(app.user.preferred_language);updateAuthUI();toast("Perfil actualizado.");}catch(err){toast(err.message);}}
  function renderGoogleStatus(){const g=app.google||{};if(!els.googleStatusTitle)return;els.googleStatusTitle.textContent=t(g.connected?`Conectada: ${g.email||"Google"}`:"No conectada");const details=[];if(!g.configured)details.push(t("La institución debe configurar OAuth antes de conectar una cuenta."));else if(!g.storage_available)details.push(t("El almacenamiento seguro de tokens no está disponible en este sistema."));else if(g.connected)details.push(g.gmail_enabled?t("Gmail habilitado únicamente para enviar avisos."):t("Perfil y correo conectados. Gmail no está habilitado."));else details.push(t("OAuth está configurado y listo para conectar."));els.googleStatusDetail.textContent=details.join(" ");els.connectGoogleButton.disabled=!g.configured||!g.storage_available;els.enableGmailButton.disabled=!g.connected||g.gmail_enabled||!g.storage_available;if(els.testGmailButton)els.testGmailButton.disabled=!g.connected||!g.gmail_enabled||!g.storage_available;els.disconnectGoogleButton.disabled=!g.connected;}
