  async function loadSessions(){try{const data=await api("/api/auth/sessions");const rows=data.sessions||[];els.sessionList.innerHTML=rows.map(s=>`<div class="admin-row"><div class="admin-row-main"><strong>${esc(s.current?t("Sesión actual"):t("Otra sesión"))}</strong><small>${formatDateTime(s.last_seen)} · ${esc(s.user_agent||t("Navegador desconocido"))}</small></div>${s.current?"":`<button class="danger-button revoke-session" data-id="${esc(s.id)}">${esc(t("Cerrar"))}</button>`}</div>`).join("");$$('.revoke-session').forEach(b=>b.addEventListener("click",()=>revokeSession(b.dataset.id)));}catch(e){toast(e.message);}}
